import { existsSync, readFileSync } from "node:fs";
import { CATALOG } from "../registry/catalog.js";
import type { Registry } from "../registry/registry.js";

// Search cards: one per catalog action, all 500 of them. Retrieval ranks these; the planner only ever gets
// full cards for actions that have a handler. cards.json is generated by `npm run cards` and committed.

/** Record types used for dependency expansion (what an action needs and what it returns). */
export const ENTITY_TYPES = [
  "contact", "company", "lead", "opportunity", "pipeline", "stage", "task", "note", "tag", "smart_list",
  "custom_field", "conversation", "sms", "email", "template", "campaign", "workflow", "trigger", "form",
  "form_submission", "survey", "calendar", "appointment", "slot", "booking_page", "event", "product", "price",
  "quote", "invoice", "payment", "payment_request", "subscription", "coupon", "order", "refund", "tax_rule",
  "website", "funnel", "landing_page", "blog_post", "media_asset", "course", "lesson", "enrollment",
  "community", "community_post", "membership_plan", "review", "review_request", "listing", "ticket", "user",
  "team", "report",
] as const;

export interface CardMeta {
  description: string;
  synonyms: string[];
  produces: string | null;
  consumes: string[];
  siblings: string[];
}

export interface CardFile {
  generatedBy?: string;
  cards: Record<string, CardMeta>;
}

export interface SearchCard {
  id: string;
  name: string;
  moduleId: string;
  module: string;
  moduleDescription: string;
  description: string;
  synonyms: string[];
  produces: string | null;
  consumes: string[];
  siblings: string[];
  /** Has a handler in this build. Unavailable actions are still retrieved, so the agent can say so. */
  available: boolean;
}

const CARDS_URL = new URL("./cards.json", import.meta.url);

export function loadCardMeta(): Record<string, CardMeta> {
  return existsSync(CARDS_URL) ? (JSON.parse(readFileSync(CARDS_URL, "utf8")) as CardFile).cards : {};
}

/**
 * Joins the catalog, the generated metadata and the registry. For implemented actions the registry is the
 * source of truth (description, entities, siblings); cards.json only adds synonyms.
 */
export function buildCards(registry: Registry, meta = loadCardMeta()): SearchCard[] {
  return CATALOG.flatMap((m) =>
    m.actions.map((a) => {
      const g = meta[a.id];
      const impl = registry.get(a.id);
      return {
        id: a.id,
        name: a.name,
        moduleId: m.id,
        module: m.name,
        moduleDescription: m.description,
        description: impl?.description ?? g?.description ?? "",
        synonyms: g?.synonyms ?? [],
        produces: impl?.entities?.produces ?? g?.produces ?? null,
        consumes: impl?.entities?.consumes ?? g?.consumes ?? [],
        siblings: [...new Set([...(impl?.siblings ?? []), ...(g?.siblings ?? [])])],
        available: impl !== undefined,
      };
    }),
  );
}
